<?php
 namespace Pterodactyl\Http\Controllers\Dezerx; use Throwable; use Illuminate\Http\Request; use Illuminate\Http\Response; use Illuminate\Http\RedirectResponse; use Illuminate\Support\Facades\Crypt; use Pterodactyl\Models\Dezerx\DiscordLink; use Pterodactyl\Http\Controllers\Controller; use Pterodactyl\Services\Dezerx\ServerCreate\Discord; use Symfony\Component\HttpKernel\Exception\NotFoundHttpException; class DiscordOAuthController extends Controller { public function connect(Request $request): RedirectResponse { if (!Discord::configured()) { throw new NotFoundHttpException(); } $user = $request->user(); if ($user === null) { throw new NotFoundHttpException(); } $state = Crypt::encryptString($user->id . '|' . bin2hex(random_bytes(8))); return redirect()->away(Discord::consentUrl(route('dezerx.discord.callback'), $state)); } public function callback(Request $request): Response { try { [$userId] = explode('|', Crypt::decryptString((string) $request->query('state', '')), 2); } catch (Throwable) { return $this->finish('failed'); } $user = $request->user(); if ($user === null || (int) $userId !== (int) $user->id) { return $this->finish('mismatch'); } if (!Discord::configured()) { return $this->finish('failed'); } if (Discord::linked($user)) { return $this->finish('linked'); } $code = (string) $request->query('code', ''); if ($code === '') { return $this->finish('cancelled'); } $tokens = Discord::exchange($code, route('dezerx.discord.callback')); if ($tokens === null) { return $this->finish('failed'); } $access = (string) $tokens['access_token']; $identity = Discord::identity($access); if ($identity === null) { return $this->finish('failed'); } if (Discord::takenByAnother($identity['id'], $user)) { return $this->finish('taken'); } $joined = Discord::joinGuild($identity['id'], $access); try { DiscordLink::query()->create([ 'user_id' => $user->id, 'discord_id' => $identity['id'], 'username' => $identity['username'], 'avatar' => $identity['avatar'], 'joined_guild' => $joined, ]); } catch (Throwable) { return Discord::linked($user) ? $this->finish('linked') : $this->finish('taken'); } return $this->finish('connected', $identity['username']); } private function finish(string $status, ?string $username = null): Response { return response()->view('dezerx.discord', [ 'status' => $status, 'username' => $username, 'origin' => url('/'), ]); } } 